{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Rutin and hyperoside, both highly polar flavonoid O-glycosides, were detected in rat brain after oral administration of an E. senticosus extract, demonstrating that polyphenol glycosides can achieve CNS access despite unfavorable passive-diffusion properties.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Hyperoside, a quercetin galactoside structurally similar to the query flavonoid glycoside, was detected in rat brain after oral dosing, directly supporting brain penetration for this compound class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Astragalin, a kaempferol 3-O-glucoside, transferred across the blood-brain barrier in rat tissue-distribution studies, providing direct evidence that flavonoid glucosides can enter the CNS.",
      "evidence_role": "supportive"
    },
  {
      "card_ids": ["C03"],
      "claim": "Hydroxysafflor yellow A, a C-glycosylated polyphenol, reached 1026 ng/g in rat brain, showing that C-glycoside polyphenols can achieve meaningful brain concentrations despite very high polarity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "TLB, a glucosylated dihydrochalcone polyphenol, was significantly detected in rat brain homogenates, further supporting brain access for glycosylated polyphenols.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Cyanidin-3-O-glucoside was detected in rat brain after dietary exposure, with brain content higher than plasma, indicating that glycosylated polyphenols can accumulate in brain tissue.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Pass: despite the unfavorable physicochemical prior for passive BBB diffusion, multiple direct in vivo studies demonstrate that flavonoid and polyphenol glycosides, including O-glucosides and C-glycosides, are detected in brain after systemic administration. The query luteolin C-glucoside belongs to this same glycosylated polyphenol class, so the experimental evidence overrides the computed passive-permeability liability.",
  "evidence_gaps": [
    "No direct experimental brain or CSF measurement for the exact query molecule.",
    "Most analogue evidence is qualitative detection; quantitative unbound brain-to-plasma ratios are not consistently reported.",
    "The relative contributions of passive diffusion, active uptake, and efflux for the query are not experimentally defined.",
    "The exact C-glycosylation position on the luteolin scaffold may influence transporter interactions and brain exposure."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

